// Client-side read-your-writes token pattern
async function updateProfile(userId, data) {
  const { version } = await db.write(`profiles/${userId}`, data);
  // Store the write version in the session
  session.set('profile_version', version);
}

async function getProfile(userId) {
  const minVersion = session.get('profile_version');
  // Pass the min required version to the read;
  // replica returns RETRY_WITH_PRIMARY if it hasn't caught up
  return await db.read(`profiles/${userId}`, { minVersion });
}

