// Two concurrent writes produced sibling versions
const siblings = await riak.get('cart', userId); // returns array of siblings

if (siblings.length > 1) {
  // Custom merge: union of all cart items (never lose an item)
  const merged = siblings.reduce((acc, s) => {
    s.items.forEach(item => {
      if (!acc.find(i => i.sku === item.sku)) acc.push(item);
    });
    return acc;
  }, []);
  await riak.put('cart', userId, { items: merged });
}

